    std::cin >> length;
    std::string word;
    std::cin >> word;
    std::vector<char> chars(word.begin(), word.end());
    std::vector<int> segmentCounts(length, 0);
    int totalWords = 0;
    int segmentIndex = 0;
    int modeFlag = 0;

    if (chars[0] == '_') {
        modeFlag = 0;
    } else if (chars[0] == '(') {
        modeFlag = 1;
    }

    for (int i = 0; i < length; i++) {
        if (modeFlag == 0) {
            if (chars[i] == '_') {
                segmentIndex++;
            } else {
                if (chars[i] != '(') {
                    segmentCounts[segmentIndex]++;
                } else if (chars[i] == '(') {
                    modeFlag = 1;
                } else if (chars[i] == ')') {
                    modeFlag = 0;
                }
            }
        } else {
            if (chars[i] == ')') {
                modeFlag = 0;
                segmentIndex++;
            } else if (i > 0) {
                if (chars[i - 1] == '(' || chars[i - 1] == '_') {
                    if (chars[i] != '_' && chars[i] != '(') {
                        totalWords++;
                    }
                }
            }
        }
    }

    // Sorting segmentCounts in descending order
    for (int i = 0; i < length; i++) {
        for (int j = i; j > 0; j--) {
